<?php
require_once __DIR__ . '/tienda_helpers.php';
$ctx=require_customer();$pdo=db();if($_SERVER['REQUEST_METHOD']!=='GET')json_response(['error'=>'Método no permitido.'],405);$code=strtoupper(clean_string($_GET['codigo']??''));if($code==='')json_response(['error'=>'Escribe un código promocional.'],422);$cart=store_active_cart($pdo,$ctx['cliente_id'],false);if(!$cart)json_response(['error'=>'El carrito está vacío.'],422);$st=$pdo->prepare("SELECT d.cantidad,p.precio_venta,p.descuento FROM carrito_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.carrito_id=? AND p.estado='activo'");$st->execute([$cart['id']]);$subtotal=0;foreach($st->fetchAll() as $p)$subtotal+=store_product_price($p)*(int)$p['cantidad'];$promo=store_promo($pdo,$code);if(!$promo)json_response(['error'=>'El código no existe, venció o alcanzó su límite de usos.'],422);$discount=$promo['tipo_descuento']==='porcentaje'?$subtotal*(float)$promo['valor']/100:(float)$promo['valor'];$discount=min($subtotal,round($discount,2));$base=round($subtotal-$discount,2);$tax=round($base*store_tax($pdo)/100,2);json_response(['ok'=>true,'codigo'=>$promo['codigo'],'descuento'=>$discount,'iva'=>$tax,'total'=>round($base+$tax,2)]);
